create table prediction_options(id uuid primary key default gen_random_uuid(),match_id uuid not null references matches on delete cascade,prediction_type_id uuid not null references prediction_types on delete cascade,entity_type text not null,entity_id uuid,display_value text not null,unique(match_id,prediction_type_id,entity_type,entity_id));
alter table prediction_options enable row level security;create policy "prediction options readable" on prediction_options for select using(true);
create or replace function configure_match_predictions(fixture_provider_id text)returns integer language plpgsql security definer set search_path=public as $$declare target_match matches%rowtype;inserted int;begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception'Service role required';end if;select*into target_match from matches where provider_id=fixture_provider_id;if not found then raise exception'Match not found';end if;insert into match_prediction_types(match_id,prediction_type_id,enabled,lock_at)select target_match.id,id,true,target_match.kickoff_at from prediction_types where enabled=true on conflict(match_id,prediction_type_id)do update set enabled=excluded.enabled,lock_at=excluded.lock_at;get diagnostics inserted=row_count;return inserted;end;$$;
revoke all on function configure_match_predictions(text)from public,anon,authenticated;grant execute on function configure_match_predictions(text)to service_role;
create or replace function sync_lineup_options(fixture_provider_id text,lineup_players jsonb)returns integer language plpgsql security definer set search_path=public as $$declare target_match matches%rowtype;p jsonb;player_uuid uuid;ptype record;saved int:=0;begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception'Service role required';end if;select*into target_match from matches where provider_id=fixture_provider_id;if not found then raise exception'Match not found';end if;for p in select*from jsonb_array_elements(lineup_players)loop insert into players(provider,provider_id,name,position)values('api-football',p->>'providerId',p->>'name',p->>'position')on conflict(provider,provider_id)do update set name=excluded.name,position=excluded.position returning id into player_uuid;for ptype in select id from prediction_types where code in('FIRST_SCORER','ANYTIME_SCORER','YELLOW_CARD')and enabled=true loop insert into prediction_options(match_id,prediction_type_id,entity_type,entity_id,display_value)values(target_match.id,ptype.id,'PLAYER',player_uuid,p->>'name')on conflict(match_id,prediction_type_id,entity_type,entity_id)do update set display_value=excluded.display_value;saved:=saved+1;end loop;end loop;return saved;end;$$;
revoke all on function sync_lineup_options(text,jsonb)from public,anon,authenticated;grant execute on function sync_lineup_options(text,jsonb)to service_role;
create or replace function get_app_fixtures()returns table(provider_id text,competition text,round text,kickoff_at timestamptz,status match_status,home_id text,home_name text,home_short_name text,home_logo_url text,away_id text,away_name text,away_short_name text,away_logo_url text,home_score int,away_score int,venue text)language sql stable security definer set search_path=public as $$select m.provider_id,c.name,coalesce(r.name,'Unscheduled'),m.kickoff_at,m.status,home.provider_id,home.name,home.short_name,home.logo_url,away.provider_id,away.name,away.short_name,away.logo_url,m.home_score,m.away_score,null::text from matches m join competitions c on c.id=m.competition_id left join competition_rounds r on r.id=m.round_id join teams home on home.id=m.home_team_id join teams away on away.id=m.away_team_id where m.kickoff_at>now()-interval'7 days'order by m.kickoff_at limit 100;$$;
grant execute on function get_app_fixtures()to anon,authenticated;
create or replace function get_match_prediction_options(fixture_provider_id text)returns table(prediction_code text,entity_type text,entity_id text,display_value text)language sql stable security definer set search_path=public as $$select pt.code,po.entity_type,case when po.entity_type='PLAYER'then pl.provider_id else po.entity_id::text end,po.display_value from matches m join match_prediction_types mpt on mpt.match_id=m.id and mpt.enabled=true join prediction_types pt on pt.id=mpt.prediction_type_id and pt.enabled=true left join prediction_options po on po.match_id=m.id and po.prediction_type_id=pt.id left join players pl on pl.id=po.entity_id where m.provider_id=fixture_provider_id order by pt.points,po.display_value;$$;
grant execute on function get_match_prediction_options(text)to anon,authenticated;
